mapper.select:
select ouvs.id, ouvs.user_id, ouvs.voc_id, ouvs.sentence, ouvs.meaning, ouvs.voc_content
from user_voc_sentence ouvs inner join
   (select voc_id
   from user_voc_sentence where user_id=#{userId}
       group by voc_id limit #{limit} offset #{offset}
   ) tmp on ouvs.user_id=#{userId} and ouvs.voc_id= tmp.voc_id
where ouvs.is_deleted = 0
